#include <bits/stdc++.h>
using namespace std;

void inputInt(int &x) {
    x = 0; bool neg = false; char ch;
    do {
        ch = getchar();
        if (ch == '-') neg = true;
    } while (!isdigit(ch));
    while (isdigit(ch)) {
        x = x * 10 + (ch - '0');
        ch = getchar();
    }
    if (neg) x = -x;
}

void inputLongLong(long long &x) {
    x = 0; bool neg = false; char ch;
    do {
        ch = getchar();
        if (ch == '-') neg = true;
    } while (!isdigit(ch));
    while (isdigit(ch)) {
        x = x * 10 + (ch - '0');
        ch = getchar();
    }
    if (neg) x = -x;
}

long long n, k, mod;
int factorial[262155], invFactorial[262155], logArr[262155], count2[262155];
int dp[262155][31];
bool visited[262155][31];
vector<pair<int, int>> history;

int countDiv2(int x) {
    int count = 0;
    while (x && (x & 1) == 0) {
        ++count; x >>= 1;
    }
    return count;
}

int fastPow(int base, long long exp) {
    int result = 1;
    while (exp > 0) {
        if (exp & 1) result = (long long)result * base % mod;
        base = (long long)base * base % mod; exp >>= 1;
    }
    return result;
}

int choose(int n, int m) {
    return (long long)factorial[n] * invFactorial[m] % mod * invFactorial[n - m] % mod;
}

int recurse(int n, int k) {
    if (n == 0) return 1;
    if (k == 0) return 0;
    if (dp[n][k] != -1) return dp[n][k];
    int res = 0;
    int limit = (1 << logArr[n]);
    for (int i = n; i >= limit; i -= 2) {
        res = (res + (long long)choose(n, i) * recurse(n - i, k - 1) % mod * k) % mod;
    }
    return dp[n][k] = res;
}

int performBFS(int n, int k) {
    static queue<pair<int, int>> q;
    q.push({n, k});
    while (!q.empty()) {
        auto [x, y] = q.front(); q.pop();
        history.emplace_back(x, y);
        if (x == 0 || y == 0) continue;
        int limit = (1 << logArr[x]);
        for (int i = x; i >= limit; i -= 2) {
            if (count2[i] + count2[x - i] == count2[x] && !visited[x - i][y - 1]) {
                visited[x - i][y - 1] = true;
                q.push({x - i, y - 1});
            }
        }
    }
    for (int i = (int)history.size() - 1; i >= 0; --i) {
        int x = history[i].first, y = history[i].second;
        if (x == 0) {
            dp[x][y] = 1; continue;
        }
        if (y == 0) {
            dp[x][y] = 0; continue;
        }
        int limit = (1 << logArr[x]);
        for (int i = x; i >= limit; i -= 2) {
            if (count2[i] + count2[x - i] == count2[x])
                dp[x][y] = (dp[x][y] + (long long)choose(x, i) * dp[x - i][y - 1] % mod * y) % mod;
        }
    }
    return dp[n][k];
}

int main() {
    inputInt(n); inputInt(k); inputInt(mod);
    factorial[0] = 1;
    memset(visited, 0, sizeof(visited));
    logArr[0] = -1;
    for (int i = 1; i <= 262150; ++i) {
        factorial[i] = (long long)factorial[i - 1] * i % mod;
        logArr[i] = logArr[i >> 1] + 1;
        count2[i] = count2[i - 1] + countDiv2(i);
    }
    invFactorial[262150] = fastPow(factorial[262150], mod - 2);
    for (int i = 262149; i > 0; --i)
        invFactorial[i] = (long long)invFactorial[i + 1] * (i + 1) % mod;
    invFactorial[0] = invFactorial[1];
    if (n & 1) {
        printf("%d\n", fastPow(k, n));
    } else {
        int cnt = 0;
        for (int i = 0; i < 62; ++i) {
            if (n & (1LL << i)) ++cnt;
        }
        int ans = fastPow(k, n);
        printf("%d\n", ((ans - performBFS(n, k)) % mod + mod) % mod);
    }
}
